from book import Chapter
c=Chapter('22')
c.add('''当一个人有了自己的知识空间，当不同人的经验可以在共同网络中发生联系，教育与科研也会改变。学习不再只是把已经整理好的结论装进一个人的头脑，科研也不再只是由少数专业人员负责、其他人等待结果的孤立活动。一个人怎样理解问题、提出疑问、尝试解决，又怎样把结果交给别人继续使用，这些过程可以连起来。

这并不要求每个人都成为所有领域的专家。恰恰因为一个人无法通晓一切，我们才需要一种能使不同知识相互补充的组织形式。''')
c.heading('每个人既是学生，也是老师')
c.src('R48220',0,start='我设想的新体制，在政治层面上',end='所形成的文明大脑所产生的智慧知识。',replacements=[('我设想的新体制，在政治层面上','在我设想的新体制中，政治层面上'),('管理文明体中所有人的，是所有人作为其中的一个神经元，所形成的文明大脑所产生的智慧知识','文明的共同知识与决策能力，来自所有人作为其中的神经元相互联系所形成的整体')])
c.src('R54886',41,end='快速增加知识。',replacements=[('未来的世界，新的体制下','我设想未来的世界，在新的体制下'),('自己在AI的加持下，快速的理解掌握这个世界的知识和信息，的任何一个微小的思想火花都会被记录被发送传播','在 AI 的帮助下，更快地理解、掌握这个世界的知识和信息。任何一个微小的思想火花，都有机会被记录、被传播'),('快速变成知识增量','经过讨论、验证与协作，变成知识增量'),('不断的如此循环迭代，快速增加知识','如此不断循环迭代，增加知识')])
c.add('''例如，一个长期照护家人的人发现，某件辅助工具在设计图上看起来合理，实际使用却让病人不舒服。他不需要先取得工程师资格，才有权指出这个问题。工程人员可以帮助描述受力与尺寸，照护者说明身体感受和使用情景，其他使用者补充不同条件，AI 帮助整理记录、比较方案。这个人一方面学习了技术知识，另一方面也在教别人认识一个此前遗漏的问题。

在这样的过程中，“学生”和“老师”是具体关系中的角色。懂得一种知识，不意味着在一切问题上都有资格替别人作决定；尚未学会一种理论，也不意味着自己的经验没有价值。一个人可以在这里请教别人，在那里帮助别人，随着学习与实践不断改变自己的位置。

因此，公共知识系统需要同时保留结论和通向结论的路。只有标准答案，学习者往往不知道为什么想到它；只有未经整理的全部过程，又会被细节淹没。合适的入口应当能够先让人看见问题，再按需要展开例子、推理、失败尝试和证据，直到他能够自己判断，并继续提出新问题。''')
c.heading('数学是在发现，还是在创造')
c.src('R49228',0,end='量子计算机及其生态等等，',replacements=[('而数学一般被认为是对宇宙的抽象本质的一种发现','而一种常见的数学观，把数学看成对宇宙抽象本质的发现'),('如果说在抽象代数大发展之前，这个说法还可以成立，因为基本上所有发现的数学规律和概念，都是已有的物理世界运行的法则。但是在此之后，我们发现很多数学上的成就，所构建的数学结构/规律/概念，都已经在现实世界中找不到对应的存在了','我们可以构造出许多数学结构、规律和概念，而不要求它们已经在眼前的物理世界中有一个对应的实物'),('相反的很多数学上的结构却会被应用到现实物理世界当中','反过来，许多数学结构又会被应用到现实世界当中'),('出现的概率几乎为零，趋近于无穷小，以至于可以认为是根本不可能存在的东西','极难自然出现的东西'),('却被人类使用高级的数学结构原理改造现实世界中的物质结构从而创造出来了新的事物','可以由人类运用数学与物理知识，改造物质结构，创造出来'),('而这个发明所依据的数学结构也可以被认为是被发明出来的','而这个发明所依据的数学结构，是否也包含了人的创造，值得进一步追问'),('再比如基于概率论和希尔伯特空间构造的量子计算机及其生态等等，','再比如对量子计算结构的探索。')],note='作者的数学哲学发问；删去未经支持的数学史概括与绝对概率断言，保留发现和构造的核心问题，改动逐项侧录')
c.add('''“发现”与“创造”在这里不必互相排斥。我们选择规则、提出定义、设计一种结构，这里有创造的活动；规则确定以后，有些关系并不依照个人愿望改变，这里又有需要发现和证明的内容。一个新的构造还可能使我们看见旧问题中没有注意到的关系。

因此，学习数学若只剩下重复既有题目的求解步骤，就没有展示数学活动的全部内容。还应当让学习者看见：问题是怎样被提出的，原有的概念为什么不够用，一个新定义解决了什么，又带来了哪些新的疑问。这里所说的创造，不是允许任意宣称结论，而是鼓励把新的构造交给推理和检验。''')
c.heading('能不能学习创造理论的过程')
c.src('R1857',5,replacements=[('3.虽然数学问题和数学理论(进一步推广到所有科学问题和科学理论范畴)有着前面提到的第三点的不同','求解一个已经定义好的数学问题，与提出一种数学理论，是两类不同的任务；这种区别也可以推广到其他科学问题和理论'),('但是考虑到','。但是考虑到'),('所以我有充足的理由相信，当前大模型的训练和推理机制，也能够用来应对这两大类问题','这使我有理由进一步研究：大模型的训练和推理机制，能否也用来应对这两大类问题')])
c.src('R1857',3,start='奥卡姆剃刀原则',end='以复杂度最小化来作为奖励函数？',replacements=[('奥卡姆剃刀原则，牛顿自然哲学四原则，柯氏复杂度，就是这个奖励函数在不同历史时期的名字','奥卡姆剃刀原则、牛顿的自然哲学原则与柯氏复杂度，使我想到一个关于理论评价的研究问题'),('在AI大模型时代','：在 AI 大模型时代')],note='作者提出的研究问题；不把不同历史原则认作已证明等价的同一个奖励函数')
c.add('''要研究这个问题，先要说清楚“同等语义”怎样比较。把一段说明删短，未必保留了它的条件；把许多内容藏进一个名字，也不等于减少了理解与执行所需要的工作。反过来，增加一个例子虽然使文字变长，却可能让人更快理解，并减少误用。理论表达、模型表示、证明长度、学习成本与执行成本，需要分别记录，再考察它们之间的关系。

这也说明，为什么个人知识库要记录思想的演化。只看最后写出的公式，很难知道研究者为什么改变方向；把问题、尝试、反例和修订联系起来，才有可能研究创造过程中哪些动作起了作用。

可以先从一个很小的比较开始：面对同一组问题，一份材料只给出最后结论，另一份材料还保留概念的形成、失败尝试与修改理由。观察学习者或 AI 是否更能理解适用条件，是否更容易发现反例，能否把方法用于不同情景。这样的结果不会一次证明整个理论，却能帮助我们决定下一步应该怎样构造知识系统。''',reason='由作者的研究问题展开的教学与研究例子；是新增方案，不是已完成实验')
c.heading('大胆想象，究竟意味着什么')
c.src('R10376',41,start='不要用当前或过时的社会科学框架',end='来评估未来的社会科学和理论以及制度规则的无限可能性。',replacements=[('不要用当前或过时的社会科学框架和理论（这部分理论从当前的状态来看，甚至还处于前牛顿时期，不同理论更像是在自己的参考系坐标系中的表达，就像多列不同速度方向加速度的列车上的观察者根据自己的观察而创造出来的不同理论，这些理论之间缺乏相互转换和参照的框架和理论进行互相转换和兼容）来评估未来的社会科学和理论以及制度规则的无限可能性','我认为，不能把当前的社会科学框架当作未来制度可能性的终点。有些理论之间的关系，在我看来，更像是多列具有不同速度、方向和加速度的列车上的观察者，根据自己的观察创造出的不同描述；我们还需要研究，它们怎样互相转换、参照与兼容。对未来社会的推理，也应当考察其前提是否已经发生变化')])
c.src('R10376',41,start='而我设想的未来，这些副本之间',end='作为智能体学习和实践中的一个环节。',replacements=[('而我设想的未来，这些副本之间','例如，我设想一种远未来的可能：一个智能体的多个身体之间'),('是一个完整的意识对象，只不过同时具有存在于不同物理位置的分身物理存在','如果能够共同构成一个完整的意识对象，那么这个整体就同时具有存在于不同物理位置的分身'),('其中任何一个个体在某个外部环境中感知的认识和学到的知识，都立即被其他所有个体所拥有，消灭其中任何一个物理本体，根本就是无关紧要的','在这个假设中，其中一个身体感知的经验和学到的知识，能够被其他身体共同获得。假如整体的记忆与意识连续性可以在部分身体损失后保留，那么失去一个身体的意义，就可能不同于今天一个人的死亡'),('可以随时再生一个出来','也许能够重新生长'),('而且这种牺牲的过程和意义，也会作为','这一过程的经历，也可能作为'),('持久保留了下来','保留下来'),('作为智能体学习和实践中的一个环节。','成为这个智能体学习和实践中的一个环节。')],note='作者跨载体共同意识设想；以明确条件句保留其区别于分离副本的要点，不宣称当下已实现或损失身体无害')
c.add('''这提出的不是一个已经完成的技术结论，而是一个需要分层研究的问题：信息怎样相通，行动怎样协调，记忆怎样连续，主观经验是否以及怎样成为整体。仅仅复制资料，不能直接回答所有这些问题；反过来，也不能只按完全分离的个体来设定前提，然后宣称一切更深的连接都不可能。

这样的想象与眼前的教育、科研其实共享一种方法：不要把尚未做到的事直接写成事实，也不要把尚未做到当成永远做不到。把设想拆成能够说明的条件，把条件变成可以继续研究的问题，再用每一轮结果修正下一轮构造。文明的创造能力，就在这个不断打开问题、建立联系并付诸实践的过程中增长。''')
c.save({'reasoning':'学习与创造相接→师生角色互换→经验进入公共知识→数学发现与构造→理论创造的训练问题→跨载体智能的条件性探索','examples':['照护者与工程人员共同改进辅助工具','完整推理过程与结论材料的比较','互联身体与分离副本的区别'],'objections':['人人参与是否取消专业知识','数学创造是否意味着结论任意','短文本是否必然表示更好理论','未来设想是否可直接当成现有能力'],'voice':'保留作者的问题、角色关系和远未来设想；教育例子及研究比较方案属于编辑补写','status':'初校；跨载体意识与理论训练均为待研究设想'})
